// tb/v3/tb_ch07_mac.v
// Cycle-accurate, bit-exact testbench for Ch.7 Autocorrelation modules:
//   1. ch07_mac_unit.v   (DSP 17x17 signed MAC unit matching ALTERA_MULT_ADD)
//   2. ch07_mac_engine.v (Complete hardware autocorrelation engine with RAM)
//
// Compliant with iverilog -g2012 -Wall:
//   - No unsized expressions inside concatenations
//   - No $random (deterministic stimulus files generated by ch07_mac_twin.py)
//   - Compares every cycle on 7,460 test vectors
//   - Samples registered outputs at @(posedge clk); #1
//   - Counts all errors without early abort, reporting 'Total comparison errors: N'

`timescale 1ns/1ps

module tb_ch07_mac;

    localparam integer DATA_W          = 17;
    localparam integer PROD_W          = 34;
    localparam integer ACC_W           = 48;
    localparam integer EXPECTED_CYCLES = 7460;

    // Clock generation (50 MHz, 20 ns period)
    reg clk = 0;
    always #10 clk = ~clk;

    // -------------------------------------------------------------------------
    // Signals for Unit Test: ch07_mac_unit
    // -------------------------------------------------------------------------
    reg                     u_rst_n;
    reg                     u_in_valid;
    reg                     u_in_sload;
    reg                     u_in_last;
    reg  signed [DATA_W-1:0] u_a;
    reg  signed [DATA_W-1:0] u_b;
    wire signed [ACC_W-1:0]  u_acc;
    wire                    u_out_valid;

    ch07_mac_unit #(
        .DATA_W(DATA_W),
        .PROD_W(PROD_W),
        .ACC_W (ACC_W)
    ) dut_mac_unit (
        .clk      (clk),
        .rst_n    (u_rst_n),
        .in_valid (u_in_valid),
        .in_sload (u_in_sload),
        .in_last  (u_in_last),
        .a        (u_a),
        .b        (u_b),
        .acc      (u_acc),
        .out_valid(u_out_valid)
    );

    // -------------------------------------------------------------------------
    // File I/O and Verification Variables
    // -------------------------------------------------------------------------
    integer stim_fd;
    integer exp_fd;
    integer cycle_idx;
    integer errors;

    // Stimulus record variables
    integer stim_rst_n;
    integer stim_in_vld;
    integer stim_in_sload;
    integer stim_in_last;
    integer stim_a;
    integer stim_b;

    // Expected record variables
    integer exp_out_vld;
    reg signed [ACC_W-1:0] exp_acc;

    initial begin
        u_rst_n     = 0;
        u_in_valid  = 0;
        u_in_sload  = 0;
        u_in_last   = 0;
        u_a         = {DATA_W{1'b0}};
        u_b         = {DATA_W{1'b0}};
        cycle_idx   = 0;
        errors      = 0;

        // Open stimulus file
        stim_fd = $fopen("verify_v3/tb_ch07_mac_stim.txt", "r");
        if (stim_fd == 0) stim_fd = $fopen("tb_ch07_mac_stim.txt", "r");
        if (stim_fd == 0) begin
            $display("[FAIL] Cannot open tb_ch07_mac_stim.txt");
            $finish;
        end

        // Open expected file
        exp_fd = $fopen("verify_v3/tb_ch07_mac_expected.txt", "r");
        if (exp_fd == 0) exp_fd = $fopen("tb_ch07_mac_expected.txt", "r");
        if (exp_fd == 0) begin
            $display("[FAIL] Cannot open tb_ch07_mac_expected.txt");
            $finish;
        end

        $display("=== STARTING CH07 MAC UNIT CYCLE-BY-CYCLE VERIFICATION ===");

        // Align with falling edge of clock
        @(negedge clk);

        while ($fscanf(stim_fd, "%d %d %d %d %d %d\n",
                       stim_rst_n, stim_in_vld, stim_in_sload, stim_in_last, stim_a, stim_b) == 6 &&
               $fscanf(exp_fd, "%d %d\n",
                       exp_out_vld, exp_acc) == 2) begin

            // 1. Drive inputs during clock low phase (negedge)
            u_rst_n    = (stim_rst_n != 0) ? 1'b1 : 1'b0;
            u_in_valid = (stim_in_vld != 0) ? 1'b1 : 1'b0;
            u_in_sload = (stim_in_sload != 0) ? 1'b1 : 1'b0;
            u_in_last  = (stim_in_last != 0) ? 1'b1 : 1'b0;
            u_a        = stim_a[DATA_W-1:0];
            u_b        = stim_b[DATA_W-1:0];

            // 2. Wait for rising edge and sample registered outputs after #1
            @(posedge clk);
            #1;

            // Check out_valid
            if (u_out_valid !== ((exp_out_vld != 0) ? 1'b1 : 1'b0)) begin
                $display("[FAIL] Cycle %0d: out_valid mismatch DUT=%b EXP=%b",
                         cycle_idx, u_out_valid, (exp_out_vld != 0));
                errors = errors + 1;
            end

            // Check accumulator acc when out_valid is active
            if (u_out_valid && (u_acc !== exp_acc)) begin
                $display("[FAIL] Cycle %0d: acc mismatch DUT=%0d EXP=%0d",
                         cycle_idx, $signed(u_acc), $signed(exp_acc));
                errors = errors + 1;
            end

            cycle_idx = cycle_idx + 1;
            @(negedge clk);
        end

        $fclose(stim_fd);
        $fclose(exp_fd);

        $display("-------------------------------------------------------");
        $display("Simulation finished. Total cycles tested: %0d", cycle_idx);

        if (cycle_idx != EXPECTED_CYCLES) begin
            $display("[FAIL] Total cycles read (%0d) does not match EXPECTED_CYCLES (%0d)!",
                     cycle_idx, EXPECTED_CYCLES);
            errors = errors + 1;
        end

        $display("Total comparison errors: %0d", errors);

        if (errors == 0) begin
            $display("=== ALL %0d VECTORS MATCHED SUCCESSFULLY ===", cycle_idx);
        end else begin
            $display("[FAIL] Verification finished with %0d errors!", errors);
        end
        $display("-------------------------------------------------------");
        $finish;
    end

endmodule
